from pathlib import Path
import json,html
b=Path(r'D:\Colosseum-Android-Phone-Mocks-20261101\review-batches\01-sources-manga')
out=b/'finished-mocks'
manifest=json.loads((b/'INPUTS.json').read_text(encoding='utf-8-sig'))
pages=[]
for job in manifest['jobs']:
 for file in job['pages']:
  label=file.replace('.html','').replace('-',' ').title()
  pages.append({'job':job['task'],'file':file,'title':label})
styles='''*{box-sizing:border-box}body{margin:0;padding:28px;background:#101218;color:#f4f3ee;font:16px/1.55 "Segoe UI",sans-serif}main{max-width:1280px;margin:auto}h1{font-size:30px;line-height:1.2}h2{margin-top:32px;font-size:21px}p{max-width:1000px}a{color:#f0c44a}table{width:100%;border-collapse:collapse;background:#181c25}th,td{text-align:left;padding:13px 15px;border:1px solid #363c48;vertical-align:top}th{background:#222936}small,.muted{color:#b6bdc9}code{font-size:.92em;background:#242936;padding:2px 5px;border-radius:3px}.notice{padding:15px 18px;border:1px solid #77652e;background:#292518;border-radius:8px}.links{display:flex;gap:14px;flex-wrap:wrap}.tag{display:inline-block;padding:2px 8px;border:1px solid #56606d;border-radius:4px;font-size:12px}.controls{display:flex;gap:15px;flex-wrap:wrap;margin:18px 0}label{display:flex;flex-direction:column;font-size:13px}select,button{font:inherit;background:#242a35;color:#f4f3ee;border:1px solid #647085;padding:8px;border-radius:6px}button{cursor:pointer}.compare-grid{display:flex;gap:20px;align-items:flex-start}.column{flex:1;min-width:0}.frame-box{position:relative;background:#050608;overflow:hidden;border:1px solid #485263}.frame-box iframe{border:0;position:absolute;top:0;left:0;transform-origin:0 0;background:#050608}.event{min-height:48px;color:#c4cad3;font-size:12px;white-space:pre-wrap}footer{margin-top:30px;border-top:1px solid #383e48;padding-top:16px}@media(max-width:760px){body{padding:16px}.compare-grid{flex-direction:column}.column{width:100%}table{font-size:13px}}'''
rows=[]
for i,x in enumerate(pages):
 link=x['job']+'/'+x['file']
 original='../../../outputs/'+x['job']+'/'+x['file']
 state='Verified target' if i<7 else ('Constrained comparison · known size limits' if i==7 else 'Verified proposal · decision pending')
 rows.append('<tr><td><a href="'+link+'">'+html.escape(x['title'])+'</a><br><small>'+html.escape(x['job'])+'</small></td><td>'+state+'</td><td><a href="compare.html?page='+str(i)+'">Before / after</a><br><a href="'+original+'">Unmodified worker original</a></td><td><a href="compare.html?page='+str(i)+'&preset=portrait">Portrait</a> · <a href="compare.html?page='+str(i)+'&preset=landscape">Landscape</a> · <a href="compare.html?page='+str(i)+'&preset=desktop">Desktop</a></td></tr>')
body='''<h1>Batch 1 · Finished sources and manga mocks</h1><p>Corrected local HTML, original comparisons and evidence. Open a page for its editable viewport, insets, font scale and state controls. All artwork, fonts and icons are local project files. Source data and acquisition events are illustrative fixtures.</p><div class="notice"><strong>Flow decision remains explicit.</strong> The constrained original is retained as the evidence of the size problem. The completed proposal preserves the 190px cover minimum with vertical scrolling; in the tightest landscape case the existing chrome scrolls too. It is ready to inspect, not approved for app implementation.</div><p class="links"><a href="../REVIEW.md">Final review</a><a href="../QML-PORTING.md">QML porting notes</a><a href="../DECISIONS.md">Original / proposal decisions</a><a href="../COVERAGE.csv">Coverage</a><a href="../FINDINGS.csv">Findings</a><a href="../contact-sheets/index.html">Contact sheets</a></p><table><thead><tr><th>Finished page</th><th>Status</th><th>Original comparison</th><th>Quick comparison sizes</th></tr></thead><tbody>'''+''.join(rows)+'''</tbody></table><h2>Cover-flow decision</h2><p class="links"><a href="compare.html?pair=flow&preset=portrait">Original attempt / proposal · portrait</a><a href="compare.html?pair=flow&preset=landscape">Original attempt / proposal · landscape</a><a href="compare.html?pair=flow&preset=short&font=1.3&insets=24&position=gallery">Tight landscape · full enlarged book</a><a href="compare.html?pair=flow&preset=short&font=1.3&insets=24&position=bottom">Tight landscape · actions</a></p><h2>Source composition</h2><p>The seven target pages use the source components named in the porting notes. Series and chapters default to <code>Main.qml → MangaSeries</code> with the brief’s explicit wordmark/progress/More restorations. Their outside-frame selector also exposes the optional rebuilt components for comparison. It does not claim to reproduce the optional route’s complete <code>TitlePageBar</code>.</p><h2>Run locally</h2><p>Keep this folder under the supplied project root so the relative asset paths continue to resolve. From PowerShell:</p><pre><code>py -m http.server 8765 --bind 127.0.0.1 --directory "D:\Colosseum-Android-Phone-Mocks-20261101"</code></pre><p>Then open <a href="http://127.0.0.1:8765/review-batches/01-sources-manga/finished-mocks/index.html">http://127.0.0.1:8765/review-batches/01-sources-manga/finished-mocks/index.html</a>. This is a local preview command for the reviewer. No server is left running by this handoff.</p><footer>HTML verification only. No app/repository edits, builds, installation, physical-device interaction, live services or publication. Viewports and insets are provisional. Authentic project illustrations are declared stand-ins where exact manga volume jackets are unavailable.</footer>'''
def doc(title,body,script=''):return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+html.escape(title)+'</title><style>'+styles+'</style></head><body><main>'+body+'</main>'+script+'</body></html>'
(out/'index.html').write_text(doc('Batch 1 finished mocks',body),encoding='utf-8')
for job in manifest['jobs']:
 folder=out/job['task']
 text='<h1>'+html.escape(job['title'])+'</h1><p><a href="../index.html">All finished Batch 1 pages and evidence</a></p><ul>'+''.join('<li><a href="'+html.escape(file)+'">'+html.escape(file)+'</a> · <a href="../../../../outputs/'+job['task']+'/'+file+'">Original worker comparison</a></li>' for file in job['pages'])+'</ul>'
 (folder/'index.html').write_text(doc(job['title'],text),encoding='utf-8')
compare='''<p><a href="index.html">← Finished index</a></p><h1 id="heading">Before / after comparison</h1><p id="description"></p><div class="controls"><label>Page<select id="pageSelect"></select></label><label>Viewport<select id="preset"><option value="portrait">412 × 900 portrait</option><option value="landscape">900 × 412 landscape</option><option value="compact">354 × 792 portrait</option><option value="short">792 × 354 landscape</option><option value="desktop">1280 × 700 desktop</option><option value="tablet">800 × 1280 tablet</option><option value="tabletLandscape">1280 × 800 tablet</option></select></label><label>Text<select id="font"><option>1</option><option>1.3</option></select></label><label>Top / bottom inset<select id="insets"><option>0</option><option>24</option></select></label><label>State<select id="state"></select></label><label>Scroll position<select id="position"><option value="initial">Initial</option><option value="gallery">Content / gallery</option><option value="bottom">Bottom actions / final rows</option></select></label><button id="reload">Reload comparison</button></div><div class="compare-grid"><section class="column"><h2 id="leftLabel"></h2><p><a id="leftLink" target="_blank" rel="noopener">Open full page</a></p><div class="frame-box" id="leftBox"><iframe id="left" title="Original comparison"></iframe></div><p class="event" id="leftEvent"></p></section><section class="column"><h2 id="rightLabel"></h2><p><a id="rightLink" target="_blank" rel="noopener">Open full page</a></p><div class="frame-box" id="rightBox"><iframe id="right" title="Finished comparison"></iframe></div><p class="event" id="rightEvent"></p></section></div><footer>Frames render at the selected logical dimensions and are scaled together only to fit this comparison window. Frame controls remain interactive. Events shown below each frame are local mock feedback. Original worker files and frozen references are unchanged.</footer>'''
script=r'''<script>
const pages=__PAGES__,q=new URLSearchParams(location.search),$=id=>document.getElementById(id),sizes={portrait:[412,900],landscape:[900,412],compact:[354,792],short:[792,354],desktop:[1280,700],tablet:[800,1280],tabletLandscape:[1280,800]},flowPreset={portrait:"portrait",landscape:"landscape",compact:"portrait-small",short:"landscape-small",desktop:"desktop",tablet:"tablet-portrait",tabletLandscape:"tablet-landscape"};
let flowPair=q.get("pair")==="flow",selected=flowPair?7:Math.max(0,Math.min(8,Number(q.get("page"))||0)),activeSize=sizes.portrait;
$("pageSelect").innerHTML=pages.map((p,i)=>'<option value="'+i+'">'+p.title+'</option>').join("")+'<option value="flow">Flow original attempt / proposed</option>';$("pageSelect").value=flowPair?"flow":String(selected);["preset","font","insets","position"].forEach(id=>{if(q.has(id))$(id).value=q.get(id);});if(!$("preset").value)$("preset").value="portrait";
function states(){const job=pages[selected].job;let a=job.startsWith("01")?["default","provider","download","season"]:job.startsWith("02")?["default","weak","ambiguous","incomplete","combined","loading","empty"]:job.startsWith("03")?["default","long","disabled","loading","empty","search-error","metadata","metadata-zero","resolving","downloading","failed","done"]:job.startsWith("04")?(pages[selected].file.includes("chapters")?["default","expanded","language-open","page-open","long","disabled","loading","empty","error","saved-unavailable"]:["default","expanded","selected","long"]):["default","select","synopsis","downloading","failed","end","no-cover"];$("state").innerHTML=a.map(v=>'<option>'+v+'</option>').join("");}
function params(p){const [w,h]=activeSize,z=$("font").value,i=$("insets").value,state=$("state").value;const a=new URLSearchParams();if(p.job.startsWith("01")){a.set("render","1");a.set("w",w);a.set("h",h);a.set("scale",z);a.set("insetTop",i);a.set("insetBottom",i);if(["download","season"].includes(state))a.set("mode",state);}else{a.set("capture","1");a.set("top",i);a.set("bottom",i);if(p.job.startsWith("05")){a.set("preset",flowPreset[$("preset").value]);a.set("font",z);if(state!=="default")a.set("state",state);}else{a.set("scale",z);if(p.job.startsWith("02")){a.set("vw",w);a.set("vh",h);if(state!=="default")a.set("state",state);}if(p.job.startsWith("03")&&state!=="default")a.set("scene",state);if(p.job.startsWith("04")&&state!=="default")a.set(["long","disabled","loading","empty","error","saved-unavailable"].includes(state)?"fixture":"state",state);}}return a.toString();}
function scaleFrames(){const [w,h]=activeSize;for(const side of ["left","right"]){const box=$(side+"Box"),scale=Math.min(1,box.parentElement.clientWidth/w);box.style.width=w*scale+"px";box.style.height=h*scale+"px";$(side).style.width=w+"px";$(side).style.height=h+"px";$(side).style.transform="scale("+scale+")";}}
function place(frame){try{const d=frame.contentDocument,pos=$("position").value;let sc=d.querySelector("#seriesScroll,#appScroll,#rowsScroll,#resultViewport,#rows");if(pos==="bottom"){for(const el of d.querySelectorAll("*")){const css=frame.contentWindow.getComputedStyle(el);if(["auto","scroll"].includes(css.overflowY)&&el.scrollHeight>el.clientHeight)el.scrollTop=el.scrollHeight;}}if(pos==="gallery"){const v=d.querySelector("#flowViewport,.volume-stage,.chapters-section,.glass-panel,.glass");if(v&&sc){if(d.querySelector("#seriesScroll"))sc.scrollTop+=v.getBoundingClientRect().top-sc.getBoundingClientRect().top;else v.scrollIntoView({block:"start"});}}if($("state").value==="provider")d.querySelector("#providerTrigger")?.click();}catch(e){}}
function load(){flowPair=$("pageSelect").value==="flow";selected=flowPair?7:Number($("pageSelect").value);activeSize=sizes[$("preset").value];const left=flowPair?pages[7]:pages[selected],right=flowPair?pages[8]:pages[selected];$("heading").textContent=flowPair?"Original flow attempt / proposed scroll allocation":right.title+" · before / after";$("description").textContent=flowPair?"The proposed behavior retains the native cover minimum and may require vertical scrolling, including chrome at the tightest stress size. Hemanth’s product decision is pending.":"Left: unmodified worker HTML. Right: corrected HTML. These are local mock renderings, not native app captures.";for(const [side,p] of [["left",left],["right",right]]){const base=side==="left"&&!flowPair?"../../../outputs/":"";const url=base+p.job+"/"+p.file+"?"+params(p);$(side).src=url;$(side+"Link").href=base+p.job+"/"+p.file;$(side+"Label").textContent=side==="left"?(flowPair?"Original constrained attempt":"Unmodified worker output"):(flowPair?"Proposed readable flow · unapproved":"Finished target");$(side).onload=()=>setTimeout(()=>place($(side)),150);}scaleFrames();}
$("pageSelect").addEventListener("change",()=>{selected=$("pageSelect").value==="flow"?7:Number($("pageSelect").value);states();load();});["preset","font","insets","state","position"].forEach(id=>$(id).addEventListener("change",load));$("reload").addEventListener("click",load);window.addEventListener("resize",scaleFrames);states();if(q.has("state")&&[...$("state").options].some(o=>o.value===q.get("state")))$("state").value=q.get("state");load();setInterval(()=>{for(const side of ["left","right"]){try{const d=$(side).contentDocument;$(side+"Event").textContent=d.querySelector("#feedback,#reviewMessage,#labStatus,#eventOutput,#reviewStatus")?.textContent||"";}catch(e){}}},300);
</script>'''.replace('__PAGES__',json.dumps(pages,ensure_ascii=False))
(out/'compare.html').write_text(doc('Batch 1 original and finished comparison',compare,script),encoding='utf-8')
start='<h1>Batch 1 handoff</h1><p><a href="finished-mocks/index.html">Open finished mocks and original comparisons</a></p><p class="links"><a href="REVIEW.md">Review</a><a href="QML-PORTING.md">QML porting notes</a><a href="DECISIONS.md">Pending decisions</a><a href="contact-sheets/index.html">Contact sheets</a><a href="REPORT.json">Completion manifest</a></p><p>Original worker outputs and frozen sources were preserved. Only this batch folder contains corrections and review evidence.</p>'
(b/'START-HERE.html').write_text(doc('Batch 1 handoff',start),encoding='utf-8')
(b/'evidence/page-catalog.json').write_text(json.dumps(pages,indent=2),encoding='utf-8')
print(json.dumps({'pages':len(pages),'index':str(out/'index.html'),'comparison':str(out/'compare.html')},indent=2))
